u8 Mcs51::p3_r()
{
	return m_rwm ? m_p3 :
		(m_p3 | m_forced_inputs[3]) & m_port_in_cb[3]()
		& ~(BIT(m_last_line_state, MCS51_INT0_LINE) ? 4 : 0)
		& ~(BIT(m_last_line_state, MCS51_INT1_LINE) ? 8 : 0);
}

void Mcs51::p3_w(u8 data)
{
	m_p3 = data;
	// P3.1 = SFR(P3) & TxD
	if (!m_uart.txd)
		m_port_out_cb[3](m_p3 & ~0x02);
	else
		m_port_out_cb[3](m_p3);
}

